"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[9842],{99842:e=>{e.exports=JSON.parse('{"slug":"zanyatost-ssha-sentyabr-realnye-zarplaty","locale":"ru","title":"\u0412 \u0421\u0428\u0410 \u0441\u043e\u0437\u0434\u0430\u043b\u0438 \u0432 3 \u0440\u0430\u0437\u0430 \u043c\u0435\u043d\u044c\u0448\u0435 \u0440\u0430\u0431\u043e\u0447\u0438\u0445 \u043c\u0435\u0441\u0442, \u0447\u0435\u043c \u0436\u0434\u0430\u043b\u0438, \u0430 \u0437\u0430\u0440\u043f\u043b\u0430\u0442\u044b \u043f\u0440\u043e\u0438\u0433\u0440\u044b\u0432\u0430\u044e\u0442 \u0446\u0435\u043d\u0430\u043c","description":"\u0412 \u0441\u0435\u043d\u0442\u044f\u0431\u0440\u0435 \u0432 \u0421\u0428\u0410 \u0441\u043e\u0437\u0434\u0430\u043b\u0438 29 \u0442\u044b\u0441. \u0440\u0430\u0431\u043e\u0447\u0438\u0445 \u043c\u0435\u0441\u0442 \u043f\u0440\u0438 \u043f\u0440\u043e\u0433\u043d\u043e\u0437\u0435 90 \u0442\u044b\u0441., \u0437\u0430\u0440\u043f\u043b\u0430\u0442\u044b +3% \u043f\u0440\u0438 \u0438\u043d\u0444\u043b\u044f\u0446\u0438\u0438 3,4%. \u0427\u0442\u043e \u0442\u0430\u043a\u043e\u0435 \u0440\u0435\u0430\u043b\u044c\u043d\u0430\u044f \u0437\u0430\u0440\u043f\u043b\u0430\u0442\u0430 \u0438 \u0447\u0442\u043e \u0431\u0443\u0434\u0435\u0442 \u0441\u043e \u0441\u0442\u0430\u0432\u043a\u043e\u0439 \u0424\u0420\u0421.","blocks":[{"id":"b001","kind":"paragraph","text":"\u041c\u0438\u043d\u0438\u0441\u0442\u0435\u0440\u0441\u0442\u0432\u043e \u0442\u0440\u0443\u0434\u0430 \u0421\u0428\u0410 2 \u043e\u043a\u0442\u044f\u0431\u0440\u044f 2026 \u0433\u043e\u0434\u0430 \u0441\u043e\u043e\u0431\u0449\u0438\u043b\u043e, \u0447\u0442\u043e \u0432 \u0441\u0435\u043d\u0442\u044f\u0431\u0440\u0435 \u044d\u043a\u043e\u043d\u043e\u043c\u0438\u043a\u0430 \u0441\u043e\u0437\u0434\u0430\u043b\u0430 29 \u0442\u044b\u0441. \u0440\u0430\u0431\u043e\u0447\u0438\u0445 \u043c\u0435\u0441\u0442. \u0416\u0434\u0430\u043b\u0438 \u043e\u043a\u043e\u043b\u043e 90 \u0442\u044b\u0441. \u0414\u0430\u043d\u043d\u044b\u0435 \u0437\u0430 \u0438\u044e\u043b\u044c \u0438 \u0430\u0432\u0433\u0443\u0441\u0442 \u043f\u0435\u0440\u0435\u0441\u043c\u043e\u0442\u0440\u0435\u043b\u0438 \u0432\u043d\u0438\u0437 \u0432 \u0441\u0443\u043c\u043c\u0435 \u043d\u0430 60 \u0442\u044b\u0441. \u0411\u0435\u0437\u0440\u0430\u0431\u043e\u0442\u0438\u0446\u0430 \u0432\u044b\u0440\u043e\u0441\u043b\u0430 \u0441 4,1% \u0434\u043e 4,2%. \u0411\u043e\u043b\u044c\u0448\u0435 \u0432\u0441\u0435\u0433\u043e \u043b\u044e\u0434\u0435\u0439 \u043d\u0430\u043d\u044f\u043b\u0438 \u0437\u0434\u0440\u0430\u0432\u043e\u043e\u0445\u0440\u0430\u043d\u0435\u043d\u0438\u0435, 17 \u0442\u044b\u0441., \u0438 \u0441\u0442\u0440\u043e\u0438\u0442\u0435\u043b\u044c\u0441\u0442\u0432\u043e, 11 \u0442\u044b\u0441., \u0430 \u0444\u0438\u043d\u0430\u043d\u0441\u043e\u0432\u044b\u0439 \u0441\u0435\u043a\u0442\u043e\u0440 \u0441\u043e\u043a\u0440\u0430\u0442\u0438\u043b 7 \u0442\u044b\u0441. \u043c\u0435\u0441\u0442."},{"id":"b002","kind":"paragraph","text":"\u0421\u043b\u0430\u0431\u0435\u0435 \u0432\u0441\u0435\u0433\u043e \u0432 \u0441\u0435\u043d\u0442\u044f\u0431\u0440\u044c\u0441\u043a\u043e\u043c \u043e\u0442\u0447\u0451\u0442\u0435 \u0432\u044b\u0433\u043b\u044f\u0434\u044f\u0442 \u0437\u0430\u0440\u043f\u043b\u0430\u0442\u044b. \u0421\u0440\u0435\u0434\u043d\u0435\u0447\u0430\u0441\u043e\u0432\u043e\u0439 \u0437\u0430\u0440\u0430\u0431\u043e\u0442\u043e\u043a \u0432 \u0421\u0428\u0410 \u0432\u044b\u0440\u043e\u0441 \u0432\u0441\u0435\u0433\u043e \u043d\u0430 0,1% \u0437\u0430 \u043c\u0435\u0441\u044f\u0446, \u044d\u0442\u043e \u0441\u0430\u043c\u044b\u0439 \u0441\u043b\u0430\u0431\u044b\u0439 \u0440\u043e\u0441\u0442 \u0441 \u0434\u0435\u043a\u0430\u0431\u0440\u044f 2025 \u0433\u043e\u0434\u0430. \u0417\u0430 \u0433\u043e\u0434 \u0437\u0430\u0440\u043f\u043b\u0430\u0442\u044b \u0432\u044b\u0440\u043e\u0441\u043b\u0438 \u043d\u0430 3%, \u043c\u0435\u0434\u043b\u0435\u043d\u043d\u0435\u0435 \u0432\u0441\u0435\u0433\u043e \u0441 \u043c\u0430\u044f 2021 \u0433\u043e\u0434\u0430. \u0426\u0435\u043d\u044b \u0432 \u0421\u0428\u0410 \u043f\u0440\u0438 \u044d\u0442\u043e\u043c \u0440\u0430\u0441\u0442\u0443\u0442 \u043d\u0430 3,4% \u0432 \u0433\u043e\u0434, \u043f\u043e \u043f\u043e\u0441\u043b\u0435\u0434\u043d\u0438\u043c \u0434\u0430\u043d\u043d\u044b\u043c \u0437\u0430 \u0430\u0432\u0433\u0443\u0441\u0442. \u041d\u0430 \u0441\u0432\u043e\u044e \u0437\u0430\u0440\u043f\u043b\u0430\u0442\u0443 \u0430\u043c\u0435\u0440\u0438\u043a\u0430\u043d\u0435\u0446 \u043c\u043e\u0436\u0435\u0442 \u043a\u0443\u043f\u0438\u0442\u044c \u043c\u0435\u043d\u044c\u0448\u0435, \u0447\u0435\u043c \u0433\u043e\u0434 \u043d\u0430\u0437\u0430\u0434."},{"id":"b003","kind":"paragraph","text":"\u042d\u0442\u043e \u0438 \u0435\u0441\u0442\u044c \u0440\u0430\u0437\u043d\u0438\u0446\u0430 \u043c\u0435\u0436\u0434\u0443 \u043d\u043e\u043c\u0438\u043d\u0430\u043b\u044c\u043d\u043e\u0439 \u0438 \u0440\u0435\u0430\u043b\u044c\u043d\u043e\u0439 \u0437\u0430\u0440\u043f\u043b\u0430\u0442\u043e\u0439. \u041d\u043e\u043c\u0438\u043d\u0430\u043b\u044c\u043d\u0430\u044f \u0437\u0430\u0440\u043f\u043b\u0430\u0442\u0430 \u044d\u0442\u043e \u0441\u0443\u043c\u043c\u0430 \u0432 \u0440\u0430\u0441\u0447\u0451\u0442\u043d\u043e\u043c \u043b\u0438\u0441\u0442\u043a\u0435. \u0420\u0435\u0430\u043b\u044c\u043d\u0430\u044f \u043f\u043e\u043a\u0430\u0437\u044b\u0432\u0430\u0435\u0442, \u0441\u043a\u043e\u043b\u044c\u043a\u043e \u043d\u0430 \u043d\u0435\u0451 \u043c\u043e\u0436\u043d\u043e \u043a\u0443\u043f\u0438\u0442\u044c: \u0438\u0437 \u0440\u043e\u0441\u0442\u0430 \u0437\u0430\u0440\u043f\u043b\u0430\u0442\u044b \u0432\u044b\u0447\u0438\u0442\u0430\u044e\u0442 \u0440\u043e\u0441\u0442 \u0446\u0435\u043d. \u0415\u0441\u043b\u0438 \u0441\u0440\u0430\u0432\u043d\u0438\u0442\u044c \u0440\u043e\u0441\u0442 \u0437\u0430\u0440\u043f\u043b\u0430\u0442 \u0437\u0430 \u0441\u0435\u043d\u0442\u044f\u0431\u0440\u044c \u0441 \u0438\u043d\u0444\u043b\u044f\u0446\u0438\u0435\u0439 \u0437\u0430 \u0430\u0432\u0433\u0443\u0441\u0442, \u0440\u0435\u0430\u043b\u044c\u043d\u0430\u044f \u0437\u0430\u0440\u043f\u043b\u0430\u0442\u0430 \u0432 \u0421\u0428\u0410 \u043f\u0430\u0434\u0430\u0435\u0442 \u043f\u0440\u0438\u043c\u0435\u0440\u043d\u043e \u043d\u0430 0,4% \u0432 \u0433\u043e\u0434 (1,03 / 1,034). \u0412 \u0420\u043e\u0441\u0441\u0438\u0438 \u0432 \u0438\u044e\u043b\u0435 2026 \u0433\u043e\u0434\u0430 \u0441\u0440\u0435\u0434\u043d\u044f\u044f \u0437\u0430\u0440\u043f\u043b\u0430\u0442\u0430 \u0432\u044b\u0440\u043e\u0441\u043b\u0430 \u043d\u0430 9,5%, \u0434\u043e 109,5 \u0442\u044b\u0441. \u0440\u0443\u0431\u043b\u0435\u0439, \u0430 \u0440\u0435\u0430\u043b\u044c\u043d\u0430\u044f \u043d\u0430 3,3%. \u0421\u0440\u0430\u0432\u043d\u0435\u043d\u0438\u0435 \u043f\u0440\u0438\u043c\u0435\u0440\u043d\u043e\u0435: \u043c\u0435\u0441\u044f\u0446\u044b \u0438 \u043c\u0435\u0442\u043e\u0434\u0438\u043a\u0438 \u043f\u043e\u0434\u0441\u0447\u0451\u0442\u0430 \u0432 \u0434\u0432\u0443\u0445 \u0441\u0442\u0440\u0430\u043d\u0430\u0445 \u0440\u0430\u0437\u043d\u044b\u0435. \u0418 \u0432 \u0420\u043e\u0441\u0441\u0438\u0438 \u0440\u043e\u0441\u0442 \u0447\u0443\u0442\u044c \u0437\u0430\u043c\u0435\u0434\u043b\u0438\u043b\u0441\u044f: \u0432 \u0438\u044e\u043d\u0435 \u0431\u044b\u043b\u043e 3,4%."},{"id":"b004","kind":"paragraph","text":"\u0414\u043b\u044f \u0424\u0435\u0434\u0435\u0440\u0430\u043b\u044c\u043d\u043e\u0439 \u0440\u0435\u0437\u0435\u0440\u0432\u043d\u043e\u0439 \u0441\u0438\u0441\u0442\u0435\u043c\u044b \u0421\u0428\u0410 \u0441\u043b\u0430\u0431\u044b\u0439 \u0440\u044b\u043d\u043e\u043a \u0442\u0440\u0443\u0434\u0430 \u044d\u0442\u043e \u0430\u0440\u0433\u0443\u043c\u0435\u043d\u0442 \u043d\u0435 \u0441\u043f\u0435\u0448\u0438\u0442\u044c. \u0417\u0430 \u043d\u0435\u0434\u0435\u043b\u044e \u0448\u0430\u043d\u0441 \u043f\u043e\u0432\u044b\u0448\u0435\u043d\u0438\u044f \u0441\u0442\u0430\u0432\u043a\u0438 \u043d\u0430 \u0437\u0430\u0441\u0435\u0434\u0430\u043d\u0438\u0438 27–28 \u043e\u043a\u0442\u044f\u0431\u0440\u044f \u0443\u043f\u0430\u043b \u0432 \u043e\u0446\u0435\u043d\u043a\u0435 \u0440\u044b\u043d\u043a\u0430 \u0441 64% \u043f\u0440\u0438\u043c\u0435\u0440\u043d\u043e \u0434\u043e 20%: \u0441\u043d\u0430\u0447\u0430\u043b\u0430 \u0438\u0437-\u0437\u0430 \u0434\u0430\u043d\u043d\u044b\u0445 \u043f\u043e \u0438\u043d\u0444\u043b\u044f\u0446\u0438\u0438, \u043f\u043e\u0442\u043e\u043c \u0438\u0437-\u0437\u0430 \u043e\u0442\u0447\u0451\u0442\u0430 \u043e \u0437\u0430\u043d\u044f\u0442\u043e\u0441\u0442\u0438. \u041d\u043e \u0438\u043d\u0444\u043b\u044f\u0446\u0438\u044f 3,4% \u0432\u0441\u0451 \u0435\u0449\u0451 \u0437\u0430\u043c\u0435\u0442\u043d\u043e \u0432\u044b\u0448\u0435 \u0446\u0435\u043b\u0438 2%, \u043f\u043e\u044d\u0442\u043e\u043c\u0443 \u0440\u044b\u043d\u043e\u043a \u0436\u0434\u0451\u0442 \u043d\u0435 \u043e\u0442\u043a\u0430\u0437\u0430 \u043e\u0442 \u043f\u043e\u0432\u044b\u0448\u0435\u043d\u0438\u044f, \u0430 \u043f\u0435\u0440\u0435\u043d\u043e\u0441\u0430: \u0432 \u0434\u0435\u043a\u0430\u0431\u0440\u0435 \u0435\u0433\u043e \u043f\u043e-\u043f\u0440\u0435\u0436\u043d\u0435\u043c\u0443 \u0436\u0434\u0443\u0442 \u0438 \u043a\u0440\u0443\u043f\u043d\u044b\u0435 \u0431\u0430\u043d\u043a\u0438, \u043d\u0430\u043f\u0440\u0438\u043c\u0435\u0440 Goldman Sachs. \u0414\u043e\u0445\u043e\u0434\u043d\u043e\u0441\u0442\u044c 10-\u043b\u0435\u0442\u043d\u0438\u0445 \u043e\u0431\u043b\u0438\u0433\u0430\u0446\u0438\u0439 \u0421\u0428\u0410 \u043f\u043e\u0441\u043b\u0435 \u043e\u0442\u0447\u0451\u0442\u0430 \u0441\u043d\u0430\u0447\u0430\u043b\u0430 \u0443\u043f\u0430\u043b\u0430, \u043d\u043e \u043a \u043a\u043e\u043d\u0446\u0443 \u0434\u043d\u044f \u0432\u044b\u0440\u043e\u0441\u043b\u0430 \u0434\u043e 5,28%. \u0421\u0442\u0430\u0432\u043a\u0430 \u0424\u0420\u0421 \u0441\u0435\u0439\u0447\u0430\u0441 3,75–4%."},{"id":"b005","kind":"paragraph","text":"\u0420\u043e\u0441\u0441\u0438\u0439\u0441\u043a\u043e\u0433\u043e \u0447\u0438\u0442\u0430\u0442\u0435\u043b\u044f \u0430\u043c\u0435\u0440\u0438\u043a\u0430\u043d\u0441\u043a\u0438\u0439 \u043e\u0442\u0447\u0451\u0442 \u043a\u0430\u0441\u0430\u0435\u0442\u0441\u044f \u0447\u0435\u0440\u0435\u0437 \u043a\u0443\u0440\u0441 \u0434\u043e\u043b\u043b\u0430\u0440\u0430, \u0438 \u0442\u044f\u043d\u0435\u0442 \u043e\u043d \u0434\u043e\u043b\u043b\u0430\u0440 \u0432 \u0440\u0430\u0437\u043d\u044b\u0435 \u0441\u0442\u043e\u0440\u043e\u043d\u044b. \u041f\u0435\u0440\u0435\u043d\u043e\u0441 \u043f\u043e\u0432\u044b\u0448\u0435\u043d\u0438\u044f \u0441\u0442\u0430\u0432\u043a\u0438 \u0434\u0435\u043b\u0430\u0435\u0442 \u0434\u043e\u043b\u043b\u0430\u0440 \u0447\u0443\u0442\u044c \u043c\u0435\u043d\u0435\u0435 \u043f\u0440\u0438\u0432\u043b\u0435\u043a\u0430\u0442\u0435\u043b\u044c\u043d\u044b\u043c, \u0438 \u0432 \u043f\u043e\u043d\u0435\u0434\u0435\u043b\u044c\u043d\u0438\u043a, 5 \u043e\u043a\u0442\u044f\u0431\u0440\u044f, \u043e\u043d \u043d\u0435\u043c\u043d\u043e\u0433\u043e \u043e\u0441\u043b\u0430\u0431 \u043a \u0434\u0440\u0443\u0433\u0438\u043c \u0432\u0430\u043b\u044e\u0442\u0430\u043c. \u041d\u043e \u043e\u0431\u043b\u0438\u0433\u0430\u0446\u0438\u0438 \u0421\u0428\u0410 \u043f\u043e-\u043f\u0440\u0435\u0436\u043d\u0435\u043c\u0443 \u043f\u043b\u0430\u0442\u044f\u0442 \u0431\u043e\u043b\u044c\u0448\u0435 5%, \u0438 \u044d\u0442\u043e \u0434\u0435\u0440\u0436\u0438\u0442 \u0441\u043f\u0440\u043e\u0441 \u043d\u0430 \u0434\u043e\u043b\u043b\u0430\u0440. \u041d\u0430 \u0440\u0443\u0431\u043b\u044c, \u0446\u0435\u043d\u044b \u0438 \u0441\u0442\u0430\u0432\u043a\u0438 \u0432 \u0420\u043e\u0441\u0441\u0438\u0438 \u0441\u0438\u043b\u044c\u043d\u0435\u0435 \u0432\u043b\u0438\u044f\u044e\u0442 \u043d\u0435\u0444\u0442\u044c \u0438 \u0440\u0435\u0448\u0435\u043d\u0438\u044f \u0411\u0430\u043d\u043a\u0430 \u0420\u043e\u0441\u0441\u0438\u0438. \u0421\u043b\u0435\u0434\u0443\u044e\u0449\u0438\u0439 \u043e\u0442\u0447\u0451\u0442 \u043e \u0437\u0430\u043d\u044f\u0442\u043e\u0441\u0442\u0438 \u0432 \u0421\u0428\u0410 \u0432\u044b\u0439\u0434\u0435\u0442 6 \u043d\u043e\u044f\u0431\u0440\u044f, \u0443\u0436\u0435 \u043f\u043e\u0441\u043b\u0435 \u043e\u043a\u0442\u044f\u0431\u0440\u044c\u0441\u043a\u043e\u0433\u043e \u0437\u0430\u0441\u0435\u0434\u0430\u043d\u0438\u044f \u0424\u0420\u0421."},{"id":"b006","kind":"paragraph","text":"\u0414\u043b\u044f \u0442\u0435\u0445, \u043a\u0442\u043e \u0434\u0435\u0440\u0436\u0438\u0442 \u0434\u043e\u043b\u043b\u0430\u0440\u044b, \u0432\u044b\u0431\u043e\u0440 \u0442\u0430\u043a\u043e\u0439. \u041f\u0440\u043e\u0434\u0430\u0432\u0430\u0442\u044c \u0438\u0445 \u043f\u043e\u0441\u043b\u0435 \u0441\u043b\u0430\u0431\u043e\u0433\u043e \u043e\u0442\u0447\u0451\u0442\u0430 \u0437\u043d\u0430\u0447\u0438\u0442 \u0441\u0442\u0430\u0432\u0438\u0442\u044c \u043d\u0430 \u0442\u043e, \u0447\u0442\u043e \u0424\u0420\u0421 \u0441\u043e\u0432\u0441\u0435\u043c \u043e\u0442\u043a\u0430\u0436\u0435\u0442\u0441\u044f \u043e\u0442 \u043f\u043e\u0432\u044b\u0448\u0435\u043d\u0438\u044f \u0441\u0442\u0430\u0432\u043a\u0438, \u0430 \u044d\u0442\u043e\u0433\u043e \u043d\u0438\u043a\u0442\u043e \u043d\u0435 \u043e\u0431\u0435\u0449\u0430\u043b. \u041f\u043e\u043a\u0443\u043f\u0430\u0442\u044c \u0432 \u0440\u0430\u0441\u0447\u0451\u0442\u0435 \u043d\u0430 \u0440\u043e\u0441\u0442 \u0434\u043e\u043b\u043b\u0430\u0440\u0430 \u0442\u043e\u0436\u0435 \u0440\u0438\u0441\u043a\u043e\u0432\u0430\u043d\u043d\u043e: \u0435\u0441\u043b\u0438 \u0431\u0435\u0437\u0440\u0430\u0431\u043e\u0442\u0438\u0446\u0430 \u043f\u0440\u043e\u0434\u043e\u043b\u0436\u0438\u0442 \u0440\u0430\u0441\u0442\u0438, \u0424\u0420\u0421 \u043c\u043e\u0436\u0435\u0442 \u043e\u0442\u043a\u0430\u0437\u0430\u0442\u044c\u0441\u044f \u0438 \u043e\u0442 \u0434\u0435\u043a\u0430\u0431\u0440\u044c\u0441\u043a\u043e\u0433\u043e \u043f\u043e\u0432\u044b\u0448\u0435\u043d\u0438\u044f. \u0421\u0442\u0430\u043d\u0435\u0442 \u043b\u0438 \u0441\u043b\u0430\u0431\u043e\u0441\u0442\u044c \u0440\u044b\u043d\u043a\u0430 \u0442\u0440\u0443\u0434\u0430 \u0442\u0440\u0435\u043d\u0434\u043e\u043c, \u043f\u043e\u043a\u0430 \u043d\u0435\u0438\u0437\u0432\u0435\u0441\u0442\u043d\u043e."},{"id":"b007","kind":"heading","text":"\u0421\u043a\u043e\u043b\u044c\u043a\u043e \u0440\u0430\u0431\u043e\u0447\u0438\u0445 \u043c\u0435\u0441\u0442 \u0441\u043e\u0437\u0434\u0430\u043b\u0438 \u0432 \u0421\u0428\u0410 \u0432 \u0441\u0435\u043d\u0442\u044f\u0431\u0440\u0435 2026 \u0433\u043e\u0434\u0430?"},{"id":"b008","kind":"paragraph","text":"29 \u0442\u044b\u0441. \u043f\u0440\u0438 \u043f\u0440\u043e\u0433\u043d\u043e\u0437\u0435 \u043e\u043a\u043e\u043b\u043e 90 \u0442\u044b\u0441. \u0414\u0430\u043d\u043d\u044b\u0435 \u0437\u0430 \u0438\u044e\u043b\u044c \u0438 \u0430\u0432\u0433\u0443\u0441\u0442 \u043f\u0435\u0440\u0435\u0441\u043c\u043e\u0442\u0440\u0435\u043b\u0438 \u0432\u043d\u0438\u0437 \u043d\u0430 60 \u0442\u044b\u0441., \u0431\u0435\u0437\u0440\u0430\u0431\u043e\u0442\u0438\u0446\u0430 \u0432\u044b\u0440\u043e\u0441\u043b\u0430 \u0441 4,1% \u0434\u043e 4,2%."},{"id":"b009","kind":"heading","text":"\u0427\u0442\u043e \u0442\u0430\u043a\u043e\u0435 \u0440\u0435\u0430\u043b\u044c\u043d\u0430\u044f \u0437\u0430\u0440\u043f\u043b\u0430\u0442\u0430?"},{"id":"b010","kind":"paragraph","text":"\u042d\u0442\u043e \u0437\u0430\u0440\u043f\u043b\u0430\u0442\u0430 \u0441 \u0443\u0447\u0451\u0442\u043e\u043c \u0440\u043e\u0441\u0442\u0430 \u0446\u0435\u043d, \u0442\u043e \u0435\u0441\u0442\u044c \u0442\u043e, \u0441\u043a\u043e\u043b\u044c\u043a\u043e \u043d\u0430 \u043d\u0435\u0451 \u043c\u043e\u0436\u043d\u043e \u043a\u0443\u043f\u0438\u0442\u044c. \u0412 \u0421\u0428\u0410 \u0437\u0430\u0440\u043f\u043b\u0430\u0442\u044b \u0437\u0430 \u0433\u043e\u0434 \u0432\u044b\u0440\u043e\u0441\u043b\u0438 \u043d\u0430 3% \u043f\u0440\u0438 \u0438\u043d\u0444\u043b\u044f\u0446\u0438\u0438 3,4%, \u043f\u043e\u044d\u0442\u043e\u043c\u0443 \u0440\u0435\u0430\u043b\u044c\u043d\u0430\u044f \u0437\u0430\u0440\u043f\u043b\u0430\u0442\u0430 \u043f\u0430\u0434\u0430\u0435\u0442 \u043f\u0440\u0438\u043c\u0435\u0440\u043d\u043e \u043d\u0430 0,4%. \u0412 \u0420\u043e\u0441\u0441\u0438\u0438 \u0432 \u0438\u044e\u043b\u0435 \u0440\u0435\u0430\u043b\u044c\u043d\u044b\u0435 \u0437\u0430\u0440\u043f\u043b\u0430\u0442\u044b \u0432\u044b\u0440\u043e\u0441\u043b\u0438 \u043d\u0430 3,3%."},{"id":"b011","kind":"heading","text":"\u041f\u043e\u0432\u044b\u0441\u0438\u0442 \u043b\u0438 \u0424\u0420\u0421 \u0441\u0442\u0430\u0432\u043a\u0443 \u043f\u043e\u0441\u043b\u0435 \u0441\u043b\u0430\u0431\u043e\u0433\u043e \u043e\u0442\u0447\u0451\u0442\u0430 \u043e \u0437\u0430\u043d\u044f\u0442\u043e\u0441\u0442\u0438?"},{"id":"b012","kind":"paragraph","text":"\u0412 \u043e\u043a\u0442\u044f\u0431\u0440\u0435 \u0432\u0440\u044f\u0434 \u043b\u0438: \u0440\u044b\u043d\u043e\u043a \u043e\u0446\u0435\u043d\u0438\u0432\u0430\u0435\u0442 \u0448\u0430\u043d\u0441 \u043f\u0440\u0438\u043c\u0435\u0440\u043d\u043e \u0432 20% \u043f\u0440\u043e\u0442\u0438\u0432 64% \u043d\u0435\u0434\u0435\u043b\u0435\u0439 \u0440\u0430\u043d\u044c\u0448\u0435. \u041d\u043e \u043f\u043e\u0432\u044b\u0448\u0435\u043d\u0438\u044f \u0432 \u0434\u0435\u043a\u0430\u0431\u0440\u0435 \u0440\u044b\u043d\u043e\u043a \u0438 \u043a\u0440\u0443\u043f\u043d\u044b\u0435 \u0431\u0430\u043d\u043a\u0438 \u043f\u043e-\u043f\u0440\u0435\u0436\u043d\u0435\u043c\u0443 \u0436\u0434\u0443\u0442. \u0421\u0435\u0439\u0447\u0430\u0441 \u0441\u0442\u0430\u0432\u043a\u0430 \u0424\u0420\u0421 3,75–4%."}],"sources":[{"label":"September\'s jobs report misses: US added just 29,000 jobs, unemployment ticked up","url":"https://finance.yahoo.com/economy/article/septembers-jobs-report-shows-the-us-added-just-29000-jobs-and-unemployment-ticked-up-195320409.html"},{"label":"Inflation has been eating up wage gains for months. September was no better","url":"https://finance.yahoo.com/economy/article/inflation-has-been-eating-up-wage-gains-for-months-september-was-no-better-180727718.html"},{"label":"World Economy Latest: US employers dial back hiring, wage growth slows","url":"https://www.bloomberg.com/news/articles/2026-10-03/world-economy-latest-us-employers-dial-back-hiring-wage-growth-slows"},{"label":"Nasdaq Adds 319 Points as Rate-Hike Odds Ebb","url":"https://www.kiplinger.com/investing/stocks/nasdaq-adds-319-points-as-rate-hike-odds-ebb-stock-market-today"},{"label":"The October Fed hike just died. Here\'s what the 29K jobs report really means for rates","url":"https://www.fxstreet.com/analysis/the-october-fed-hike-just-died-heres-what-the-29k-jobs-report-really-means-for-rates-202610021806"},{"label":"Treasury Yields Drop as Weak Jobs Report Eases October Fed Rate Hike Odds","url":"https://www.indexbox.io/blog/treasury-yields-fall-after-weak-september-jobs-report-cuts-odds-of-october-fed-rate-hike/"},{"label":"Stocks upbeat, dollar wobbles as Fed hike bets recede","url":"https://www.investing.com/news/economy-news/stocks-upbeat-dollar-wobbles-as-fed-hike-bets-recede-4930982"},{"label":"Schedule of Releases for the Employment Situation","url":"https://www.bls.gov/schedule/news_release/empsit.htm"},{"label":"\u0420\u043e\u0441\u0442 \u0440\u0435\u0430\u043b\u044c\u043d\u044b\u0445 \u0437\u0430\u0440\u043f\u043b\u0430\u0442 \u0432 \u0420\u0424 \u0432 \u0438\u044e\u043b\u0435 \u0437\u0430\u043c\u0435\u0434\u043b\u0438\u043b\u0441\u044f \u0434\u043e 3,3% \u0433/\u0433","url":"https://ru.themoscowtimes.com/2026/09/30/rost-realnykh-zarplat-v-rf-v-iyule-26g-zamedlilsya-do-33-gg-a207452"}],"sourceBodySha256":"8dbaae3cc9570f53146a348a9d62855bcdad77232b7be2422c1b98c268553b25"}')}}]);